BEGIN TRANSACTION;
CREATE TABLE approved_chains(code TEXT PRIMARY KEY,name TEXT NOT NULL,format TEXT NOT NULL,source TEXT NOT NULL,checked_date TEXT NOT NULL);
CREATE TABLE branch_decisions(store_id INTEGER PRIMARY KEY,chain TEXT,decision TEXT NOT NULL,format TEXT,official_source_id TEXT,source TEXT,checked_date TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE candidate_stores (
    id INTEGER PRIMARY KEY,
    osm_id TEXT UNIQUE,
    chain TEXT,
    name TEXT NOT NULL,
    address TEXT NOT NULL,
    postal_code TEXT NOT NULL,
    city TEXT NOT NULL,
    latitude REAL NOT NULL CHECK(latitude BETWEEN 54 AND 58),
    longitude REAL NOT NULL CHECK(longitude BETWEEN 7 AND 16),
    x REAL NOT NULL CHECK(x BETWEEN 100000 AND 900000),
    y REAL NOT NULL CHECK(y BETWEEN 6000000 AND 6600000),
    source TEXT NOT NULL,
    checked_date TEXT NOT NULL
);
CREATE TABLE chain_aliases(alias TEXT PRIMARY KEY,chain TEXT NOT NULL REFERENCES approved_chains(code));
COMMIT;
